import React, { useState } from "react";
import "./clippreview.css";

function ClipPreview({ videoUrl, videoThumbnail, clipPaths }) {
  const [isPlaying, setIsPlaying] = useState(false);

  // Toggle play/pause logic
  const handlePlayPause = () => {
    setIsPlaying((prev) => !prev);
  };

  return (
    <div className="clipping-app">
      {/* Header Section */}
      <header className="header">
        <h1 className="logo">
          <span className="bold">Channel-</span>
          <span className="highlight">IQ</span>
        </h1>
        <nav className="nav">
          <a href="#clipper">Clipper</a>
          <a href="#seo">SEO</a>
          <a href="#thumbnail">Thumbnail</a>
          <a href="#pricing">Pricing</a>
          <button className="sign-in">Sign in</button>
          <button className="sign-up">Sign up</button>
        </nav>
      </header>

      {/* Main Content */}
      <main className="main-content">
        {/* Clipper Section */}
        <section className="clipper-section">
          <button className="clipper-btn">Clipper</button>

          {/* Long Video Section */}
          <div className="long-video">
            <h2>Your long video</h2>
            <div className="video-preview">
              {videoUrl ? (
                <video src={videoUrl} controls className="preview-video" />
              ) : (
                <img
                  src={videoThumbnail || "https://via.placeholder.com/300x200"}
                  alt="Video Thumbnail"
                  className="preview-image"
                />
              )}
            </div>
          </div>

          {/* Viral Clips Section */}
          <div className="viral-clips">
            <h3>Your Viral Clips</h3>
            <div className="clip-thumbnails">
              {/* Hardcoded Example */}
              {/* Uncomment this section to use hardcoded paths */}
              {/*
              <div>
                <video
                  src="https://example.com/clip1.mp4"
                  controls
                  className="clip-thumbnail"
                />
                <video
                  src="https://example.com/clip2.mp4"
                  controls
                  className="clip-thumbnail"
                />
                <video
                  src="https://example.com/clip3.mp4"
                  controls
                  className="clip-thumbnail"
                />
              </div>
              */}

              {/* Dynamic Rendering */}
              {clipPaths && clipPaths.length > 0 ? (
                clipPaths.map((path, index) => (
                  <video
                    key={index}
                    src={path.clip_path} // Assuming clipPaths is an array of objects with "clip_path"
                    controls
                    className="clip-thumbnail"
                  />
                ))
              ) : (
                <p>No clips available to display.</p>
              )}
            </div>
          </div>
        </section>
      </main>
    </div>
  );
}

export default ClipPreview;
